SELECT round(
         ST_Distance(
           ST_Transform(ST_Point(5.0, 9.0), 'EPSG:4326', 'EPSG:32631', always_xy := true),
           ST_Transform(geometry, 'EPSG:4326', 'EPSG:32631', always_xy := true)
         ) / 1000.0,
         1
       ) AS distance_km
FROM countries
WHERE name = 'Benin';
